    /// <summary>
    /// Returns information about a file with a map thumbnail in PNG format. Only map thumbnail files with size less than 1MB can be downloaded
    /// </summary>
    public Task<TdLib.TdApi.Objects.File> GetMapThumbnailFileAsync(Location location = default, int zoom = default, int width = default, int height = default, int scale = default, long chatId = default)
    {

           using var activity =  StartCallActivity("GetMapThumbnailFileAsync", typeof(GetMapThumbnailFile).FullName ?? "GetMapThumbnailFileAsync");

           try
           {
             return client.GetMapThumbnailFileAsync(location, zoom, width, height, scale, chatId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
